export type ParsedBeginRebalanceInstruction<
  TProgram extends string = typeof INDEX_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    executor: TAccountMetas[0];
    config: TAccountMetas[1];
    index: TAccountMetas[2];
    vaultOutAta: TAccountMetas[3];
    executorOutAta: TAccountMetas[4];
    vaultInAta: TAccountMetas[5];
    instructions: TAccountMetas[6];
    tokenProgram: TAccountMetas[7];
    token2022Program: TAccountMetas[8];
  };
  data: BeginRebalanceInstructionData;
};

export function parseBeginRebalanceInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedBeginRebalanceInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 9,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      executor: getNextAccount(),
      config: getNextAccount(),
      index: getNextAccount(),
      vaultOutAta: getNextAccount(),
      executorOutAta: getNextAccount(),
      vaultInAta: getNextAccount(),
      instructions: getNextAccount(),
      tokenProgram: getNextAccount(),
      token2022Program: getNextAccount(),
    },
    data: getBeginRebalanceInstructionDataDecoder().decode(instruction.data),
  };
}
